1	// Catalog of LM models + backends for the cascade (STT → LM → TTS) engine.
2	//
3	// Single source of truth, edited as data in `config/lm-models.json` — so changing
4	// which model the cascade uses is a config edit, not a code change, and there's no
5	// need to pull a live model list. Read by both the server route (`app/api/llm`,
6	// which resolves a backend's URL + secret env key) and the client agent config
7	// (`cascade-agent.ts`, which picks the model). Only env var *names* and public
8	// API URLs live here; secret values stay in fnox and are read server-side.
9	
10	import catalog from "@/config/lm-models.json";
11	
12	export interface LmBackendConfig {
13	  /** OpenAI-compatible chat-completions endpoint. */
14	  url: string;
15	  /** Name of the secret env var holding the bearer token (read server-side only).
16	   *  Empty string = keyless backend (local server); no Authorization header sent. */
17	  envKey: string;
18	  /** Send chat_template_kwargs.enable_thinking:false (reasoning models). Must be
19	   *  false for APIs that reject unknown fields (e.g. Mistral). */
20	  supportsThinking: boolean;
21	}
22	
23	export interface LmModel {
24	  /** Stable key used by `default` / a persona's `lmModelId`. */
25	  id: string;
26	  /** Human label (for docs / a future picker). */
27	  label: string;
28	  /** Backend id — a key of `backends`. */
29	  backend: string;
30	  /** Upstream model id (HF repo or Mistral model name). */
31	  model: string;
32	  temperature: number;
33	  maxTokens: number;
34	}
35	
36	interface LmCatalog {
37	  default: string;
38	  backends: Record<string, LmBackendConfig>;
39	  models: LmModel[];
40	}
41	
42	const CONFIG = catalog as unknown as LmCatalog;
43	
44	export const LM_BACKENDS: Record<string, LmBackendConfig> = CONFIG.backends;
45	export const LM_MODELS: LmModel[] = CONFIG.models;
46	
47	/** Look up a backend by id (undefined if not in the catalog). */
48	export function resolveLmBackend(id: string): LmBackendConfig | undefined {
49	  return LM_BACKENDS[id];
50	}
51	
52	/** Resolve a model by id, falling back to the catalog `default`, then the first
53	 *  entry — so a stale/empty id never breaks a call. */
54	export function resolveLmModel(id?: string): LmModel {
55	  return (
56	    (id ? LM_MODELS.find((m) => m.id === id) : undefined) ??
57	    LM_MODELS.find((m) => m.id === CONFIG.default) ??
58	    LM_MODELS[0]
59	  );
60	}
61	
62	/** The catalog default — the model every cascade persona uses unless it pins one. */
63	export const DEFAULT_LM_MODEL: LmModel = resolveLmModel(CONFIG.default);
64	
65	/** Selectable LM models for a provider's engine. Only the cascade engine draws
66	 *  from the catalog; every other engine is a single fixed realtime model (so the
67	 *  Providers view shows no model picker for them). */
68	export function lmModelsForEngine(engine?: string): LmModel[] {
69	  return engine === "cascade" ? LM_MODELS : [];
70	}
71	
72	/** MODEL label for a provider wherever the UI shows one (sidebar, call header,
73	 *  transcript drawer, providers table). Cascade reflects the *picked* catalog
74	 *  model — not the static string in lib/data.ts, which can't know the runtime
75	 *  selection; every other engine has a single fixed model. */
76	export function providerModelLabel(
77	  provider: { engine?: string; model: string },
78	  lmModelId?: string,
79	): string {
80	  return provider.engine === "cascade"
81	    ? `cascade · ${resolveLmModel(lmModelId).id}`
82	    : provider.model;
83	}
84

1	// Server-side LM stage for the STT → LM → TTS cascade engine.
2	//
3	// Streams an OpenAI-compatible chat completion from a backend chosen per request,
4	// so the cascade can swap LMs without the browser ever seeing a key. Backends and
5	// their URL + secret env key are defined in `config/lm-models.json` (the model
6	// catalog) — add one there, not here. The upstream SSE body is piped straight back
7	// to the client, which reads the `data: {...}` deltas. Reasoning models stream
8	// chain-of-thought in a separate field and emit no spoken `content` until thinking
9	// ends, so for backends with `supportsThinking` we send
10	// `chat_template_kwargs.enable_thinking:false` by default.
11	//
12	// Dev only: the secret named by each backend's `envKey` (HF_TOKEN / MISTRAL_API_KEY)
13	// is provided via fnox (`fnox exec -- bun run dev`). A backend with an empty
14	// `envKey` is keyless (local llama-server via `mise run lm-local`) — no
15	// Authorization header is sent.
16	
17	import { DEFAULT_LM_MODEL, resolveLmBackend } from "@/lib/realtime/lm-config";
18	
19	export const runtime = "nodejs";
20	export const dynamic = "force-dynamic";
21	
22	interface LlmRequest {
23	  /** Backend id from the catalog (a key of `backends` in config/lm-models.json). */
24	  backend?: string;
25	  model?: string;
26	  messages?: Array<{ role: string; content: string }>;
27	  maxTokens?: number;
28	  temperature?: number;
29	  enableThinking?: boolean;
30	}
31	
32	export async function POST(req: Request): Promise<Response> {
33	  let body: LlmRequest;
34	  try {
35	    body = (await req.json()) as LlmRequest;
36	  } catch {
37	    return Response.json({ error: "Invalid JSON body." }, { status: 400 });
38	  }
39	
40	  const backendId = body.backend ?? DEFAULT_LM_MODEL.backend;
41	  const backend = resolveLmBackend(backendId);
42	  if (!backend) {
43	    return Response.json(
44	      { error: `Unknown LM backend "${backendId}" (define it in config/lm-models.json).` },
45	      { status: 400 },
46	    );
47	  }
48	  // An empty envKey marks a keyless backend (local llama-server / mlx_lm.server);
49	  // only fail when the catalog names a secret that isn't actually set.
50	  const apiKey = REDACTED ? process.env[backend.envKey] : undefined;
51	  if (backend.envKey && !apiKey) {
52	    return Response.json(
53	      { error: `${backend.envKey} is not set on the server (provide it via fnox).` },
54	      { status: 500 },
55	    );
56	  }
57	  if (!body.model || !Array.isArray(body.messages) || body.messages.length === 0) {
58	    return Response.json({ error: "model and messages are required." }, { status: 400 });
59	  }
60	
61	  const upstreamBody: Record<string, unknown> = {
62	    model: body.model,
63	    messages: body.messages,
64	    stream: true,
65	    max_tokens: body.maxTokens ?? 256,
66	    temperature: body.temperature ?? 0.7,
67	  };
68	  // Reasoning models toggle chain-of-thought via chat_template_kwargs (ignored by
69	  // non-reasoning models). APIs that reject unknown fields (e.g. Mistral, 422) set
70	  // supportsThinking:false in the catalog, so we only send it where it's accepted.
71	  if (backend.supportsThinking) {
72	    upstreamBody.chat_template_kwargs = { enable_thinking: body.enableThinking ?? false };
73	  }
74	
75	  let upstream: Response;
76	  try {
77	    upstream = await fetch(backend.url, {
78	      method: "POST",
79	      headers: {
80	        ...(apiKey ? { Authorization: `Bearer ${apiKey}` } : {}),
81	        "Content-Type": "application/json",
82	        Accept: "text/event-stream",
83	      },
84	      body: JSON.stringify(upstreamBody),
85	    });
86	  } catch (err) {
87	    return Response.json(
88	      {
89	        error: `Failed to reach ${backendId}: ${err instanceof Error ? err.message : "network error"}`,
90	      },
91	      { status: 502 },
92	    );
93	  }
94	
95	  if (!upstream.ok || !upstream.body) {
96	    const detail = await upstream.text().catch(() => "");
97	    return Response.json(
98	      { error: `${backendId} chat completion failed`, status: upstream.status, detail },
99	      { status: 502 },
100	    );
101	  }
102	
103	  // Pipe the upstream SSE straight to the client.
104	  return new Response(upstream.body, {
105	    status: 200,
106	    headers: {
107	      "Content-Type": "text/event-stream; charset=utf-8",
108	      "Cache-Control": "no-store",
109	      Connection: "keep-alive",
110	    },
111	  });
112	}
113

