1	"use client";
2	
3	// Browser-side leg of the Mistral realtime-STT cascade. Captures the mic at
4	// 16 kHz, streams PCM16 to the local proxy (which adds the Bearer header the
5	// browser can't), and turns Mistral's streaming `transcription.text.delta`
6	// events into discrete user turns.
7	//
8	// Turn boundaries are OURS, not the model's: Mistral only emits a terminal
9	// `transcription.done` after `input_audio.end` (which closes the stream), so for
10	// a back-and-forth conversation we keep the session open and detect end-of-turn
11	// client-side with **Silero VAD** (neural, via onnxruntime-web — see
12	// `silero-vad.ts`). Silero answers "did the user stop talking?"; Mistral answers
13	// "what did they say?". This replaced an energy/RMS gate that sat below most
14	// rooms' noise floor and never fired end-of-turn. The manual "send" button
15	// (`endTurnNow`) remains as an override.
16	//
17	// The proxy lives at NEXT_PUBLIC_MISTRAL_STT_WS (default ws://localhost:3001);
18	// run it with `mise run stt-proxy`. See scripts/mistral-stt-proxy.ts.
19	//
20	// A second capture mode, `batch`, serves the LOCAL STT backend
21	// (config/voice-models.json → mlx-audio server): no WebSocket at all — the
22	// turn's PCM is buffered while the user speaks and POSTed as one WAV to
23	// /api/stt when the same Silero VAD (or the Send button) ends the turn. No
24	// live partial captions in this mode; everything else (mic graph, gating,
25	// levels, turn machine) is shared.
26	
27	import { calculateRms, float32ToPcm16Base64 } from "./xai-audio";
28	import { SileroVad } from "./silero-vad";
29	import { encodeWavPcm16 } from "./wav";
30	
31	const SAMPLE_RATE = 16000;
32	const PROC_FRAMES = 2048; // ~128 ms per audio block; a multiple of Silero's 512
33	const FLUSH_GRACE_MS = 350; // wait after flush to collect trailing deltas
34	// Silero turn-detection tunables (forwarded to SileroVad). Bump REDEMPTION_MS if
35	// it still ends turns too early; raise the thresholds if a noisy room over-triggers.
36	const VAD_REDEMPTION_MS = 900; // silence after speech that ends the turn
37	const VAD_MIN_SPEECH_MS = 250; // shortest run that counts as a real turn
38	const VAD_POSITIVE = 0.3; // speech-probability onset threshold
39	const VAD_NEGATIVE = 0.25; // speech-probability release threshold
40	// Batch mode: cap the per-turn recording (memory guard — 16 kHz mono Float32 is
41	// ~64 KB/s, so 120 s ≈ 7.5 MB). Beyond the cap the turn stops growing.
42	const BATCH_MAX_TURN_S = 120;
43	
44	export interface MistralSttOptions {
45	  /** WebSocket URL of the local proxy (e.g. ws://localhost:3001). */
46	  wsUrl: string;
47	  /** Realtime transcription model id. */
48	  model?: string;
49	  /** `realtime` (default) streams to the Mistral WS proxy; `batch` records the
50	   *  turn and POSTs one WAV to /api/stt on turn end (local backend). */
51	  mode?: "realtime" | "batch";
52	  /** Catalog backend id forwarded to /api/stt in batch mode. */
53	  sttBackend?: string;
54	  /** Running transcript of the in-progress turn (drive the live caption). */
55	  onPartial: (text: string) => void;
56	  /** A completed user turn (silence detected after speech). */
57	  onFinal: (text: string) => void;
58	  /** Connected and configured — safe to start speaking. */
59	  onReady?: () => void;
60	  /** Fatal error (proxy down, mic denied, upstream closed). */
61	  onError?: (message: string) => void;
62	}
63	
64	export class MistralStt {
65	  private readonly opts: MistralSttOptions;
66	  private ws: WebSocket | null = null;
67	  private ctx: AudioContext | null = null;
68	  private stream: MediaStream | null = null;
69	  private source: MediaStreamAudioSourceNode | null = null;
70	  private proc: ScriptProcessorNode | null = null;
71	  private vad: SileroVad | null = null;
72	
73	  // Capture gating: audio is streamed only while listening && !muted.
74	  private listening = false;
75	  private muted = false;
76	  private closed = false;
77	  private ready = false;
78	
79	  // Per-turn transcript + emit state.
80	  private turnText = "";
81	  private emitting = false;
82	  private flushTimer: ReturnType<typeof setTimeout> | null = null;
83	  private inputRms = 0;
84	
85	  // Batch mode: the turn's recorded PCM (Float32 blocks at SAMPLE_RATE).
86	  private turnChunks: Float32Array[] = [];
87	  private turnSamples = 0;
88	
89	  private get batch(): boolean {
90	    return this.opts.mode === "batch";
91	  }
92	
93	  constructor(opts: MistralSttOptions) {
94	    this.opts = opts;
95	  }
96	
97	  /** Open the mic + proxy WebSocket and configure the session. Resolves once
98	   *  the audio graph and socket are wired (not necessarily server-ready). */
99	  async start(): Promise<void> {
100	    this.closed = false;
101	    const ctx = new AudioContext({ sampleRate: SAMPLE_RATE });
102	    this.ctx = ctx;
103	
104	    const stream = await navigator.mediaDevices.getUserMedia({
105	      audio: {
106	        channelCount: 1,
107	        echoCancellation: true,
108	        noiseSuppression: true,
109	        // AGC boosts ambient noise enough to trip the VAD — keep it off so the
110	        // silence gate stays stable (same lesson as the PersonaPlex mic gate).
111	        autoGainControl: false,
112	      },
113	    });
114	    if (this.closed) {
115	      stream.getTracks().forEach((t) => t.stop());
116	      return;
117	    }
118	    this.stream = stream;
119	    if (ctx.state === "suspended") await ctx.resume();
120	
121	    const source = ctx.createMediaStreamSource(stream);
122	    this.source = source;
123	    const proc = ctx.createScriptProcessor(PROC_FRAMES, 1, 1);
124	    this.proc = proc;
125	    proc.onaudioprocess = (e) => this.onAudio(e.inputBuffer.getChannelData(0));
126	    source.connect(proc);
127	    // Required for the callback to fire in some browsers; the node writes no
128	    // output, so this does not echo the mic to the speakers.
129	    proc.connect(ctx.destination);
130	
131	    if (this.batch) {
132	      // No socket in batch mode — the mic graph is the whole session.
133	      this.ready = true;
134	      this.opts.onReady?.();
135	    } else {
136	      this.connectWs();
137	    }
138	
139	    // Load Silero VAD in parallel (model fetch + ORT init). The mic streams to
140	    // Mistral immediately; turn detection comes online once this resolves. If it
141	    // fails to load, transcription still works — the manual "send" button covers
142	    // turn ends.
143	    SileroVad.create({
144	      positiveSpeechThreshold: VAD_POSITIVE,
145	      negativeSpeechThreshold: VAD_NEGATIVE,
146	      redemptionMs: VAD_REDEMPTION_MS,
147	      minSpeechMs: VAD_MIN_SPEECH_MS,
148	      onSpeechStart: () => this.onSpeechStart(),
149	      onSpeechEnd: () => this.onSpeechEnd(),
150	      // VAD failure is non-fatal: don't tear down Mistral STT (and don't fall
151	      // back to Web Speech, which is the thing we moved away from) — just lose
152	      // auto turn-detection. The manual "send" button still ends turns.
153	      onError: (m) => console.warn(`[mistral-stt] VAD: ${m} — use the Send button`),
154	    })
155	      .then((vad) => {
156	        if (this.closed) {
157	          vad.close();
158	          return;
159	        }
160	        this.vad = vad;
161	        if (this.listening && !this.muted) vad.resume();
162	      })
163	      .catch((err) => {
164	        console.warn(
165	          `[mistral-stt] Silero VAD load failed (${err instanceof Error ? err.message : "unknown"}) — use the Send button`,
166	        );
167	      });
168	  }
169	
170	  private connectWs(): void {
171	    const model = this.opts.model ?? "voxtral-mini-transcribe-realtime-2602";
172	    const url = `${this.opts.wsUrl}?model=${encodeURIComponent(model)}`;
173	    let ws: WebSocket;
174	    try {
175	      ws = new WebSocket(url);
176	    } catch {
177	      this.opts.onError?.("STT proxy unreachable");
178	      return;
179	    }
180	    this.ws = ws;
181	    ws.onopen = () => {
182	      ws.send(
183	        JSON.stringify({
184	          type: "session.update",
185	          session: {
186	            audio_format: { encoding: "pcm_s16le", sample_rate: SAMPLE_RATE },
187	            target_streaming_delay_ms: 1000,
188	          },
189	        }),
190	      );
191	    };
192	    ws.onmessage = (ev) => this.onMessage(ev);
193	    ws.onerror = () => {
194	      if (!this.closed) this.opts.onError?.("STT proxy connection error");
195	    };
196	    ws.onclose = () => {
197	      if (!this.closed && this.ready) this.opts.onError?.("STT session closed");
198	    };
199	  }
200	
201	  private onMessage(ev: MessageEvent): void {
202	    let msg: { type?: string; text?: string };
203	    try {
204	      msg = JSON.parse(typeof ev.data === "string" ? ev.data : "{}");
205	    } catch {
206	      return;
207	    }
208	    switch (msg.type) {
209	      // Mistral marks a successful handshake with `session.created`; our
210	      // session.update on open is acked with `session.updated`. Either one
211	      // means the session is live — without `ready`, ws.onclose stays silent
212	      // and a dead socket would never trigger the Web Speech fallback.
213	      case "session.created":
214	      case "session.updated":
215	        if (!this.ready) {
216	          this.ready = true;
217	          this.opts.onReady?.();
218	        }
219	        break;
220	      case "transcription.text.delta":
221	        // Deltas only count toward a turn while we're actually listening; any
222	        // that arrive during the assistant's turn are dropped on resume.
223	        if (this.listening && !this.muted && msg.text) {
224	          this.turnText += msg.text;
225	          this.opts.onPartial(this.turnText.trim());
226	        }
227	        break;
228	      case "error":
229	        this.opts.onError?.("STT error");
230	        break;
231	      default:
232	        break;
233	    }
234	  }
235	
236	  private onAudio(input: Float32Array): void {
237	    if (this.muted || !this.listening) {
238	      this.inputRms = 0;
239	      return;
240	    }
241	    this.inputRms = calculateRms(input); // for the input-level visualizer only
242	
243	    if (this.batch) {
244	      // Record the turn locally; it's transcribed in one shot on turn end. The
245	      // buffer must copy — ScriptProcessor reuses its channel-data array.
246	      if (this.turnSamples < SAMPLE_RATE * BATCH_MAX_TURN_S && !this.emitting) {
247	        this.turnChunks.push(new Float32Array(input));
248	        this.turnSamples += input.length;
249	      }
250	    } else {
251	      const ws = this.ws;
252	      if (ws && ws.readyState === WebSocket.OPEN) {
253	        ws.send(JSON.stringify({ type: "input_audio.append", audio: float32ToPcm16Base64(input) }));
254	      }
255	    }
256	
257	    // Silero decides the turn boundaries (onSpeechEnd → endTurn).
258	    this.vad?.feed(input);
259	  }
260	
261	  /** Silero saw speech begin. If an emit was pending (user paused, then resumed
262	   *  within the flush grace), cancel it and keep building the same turn. */
263	  private onSpeechStart(): void {
264	    if (this.emitting && this.flushTimer) {
265	      clearTimeout(this.flushTimer);
266	      this.flushTimer = null;
267	      this.emitting = false;
268	    }
269	  }
270	
271	  /** Silero saw end-of-speech ⇒ end the turn (flush + emit). */
272	  private onSpeechEnd(): void {
273	    if (this.listening && !this.muted && !this.emitting) this.endTurn();
274	  }
275	
276	  /** Manually end the current turn now (the "send" button), bypassing the
277	   *  silence gate. Flushes and emits whatever has been transcribed; no-op if not
278	   *  listening or already emitting. */
279	  endTurnNow(): void {
280	    if (!this.listening || this.muted || this.emitting) return;
281	    this.endTurn();
282	  }
283	
284	  /** Realtime: flush the tail, wait briefly for trailing deltas, then emit.
285	   *  Batch: POST the recorded turn as one WAV and emit the transcription. */
286	  private endTurn(): void {
287	    if (this.batch) {
288	      void this.endTurnBatch();
289	      return;
290	    }
291	    this.emitting = true;
292	    const ws = this.ws;
293	    if (ws && ws.readyState === WebSocket.OPEN) {
294	      ws.send(JSON.stringify({ type: "input_audio.flush" }));
295	    }
296	    if (this.flushTimer) clearTimeout(this.flushTimer);
297	    this.flushTimer = setTimeout(() => {
298	      const text = this.turnText.trim();
299	      this.resetTurn();
300	      this.emitting = false;
301	      if (text) this.opts.onFinal(text);
302	    }, FLUSH_GRACE_MS);
303	  }
304	
305	  private async endTurnBatch(): Promise<void> {
306	    const chunks = this.turnChunks;
307	    this.resetTurn();
308	    if (chunks.length === 0) return;
309	    this.emitting = true;
310	    this.opts.onPartial("… transcribing");
311	    try {
312	      const backend = this.opts.sttBackend;
