36	export function useTweaks(): [Tweaks, <K extends keyof Tweaks>(key: K, value: Tweaks[K]) => void] {
37	  const [tweaks, setTweaks] = useState<Tweaks>(TWEAK_DEFAULTS);
38	
39	  // Hydrate from localStorage after mount to avoid SSR mismatch.
40	  useEffect(() => {
41	    try {
42	      const raw = localStorage.getItem(KEY);
43	      if (raw) setTweaks((prev) => ({ ...prev, ...JSON.parse(raw) }));
44	    } catch {
45	      // ignore malformed storage
46	    }
47	  }, []);
48	
49	  // Mirror dark mode to the <html> class so ElevenLabs/shadcn components follow.
50	  useEffect(() => {
51	    document.documentElement.classList.toggle("dark", tweaks.dark);
52	  }, [tweaks.dark]);
53	
54	  const setTweak = useCallback(<K extends keyof Tweaks>(key: K, value: Tweaks[K]) => {
55	    setTweaks((prev) => {
56	      const next = { ...prev, [key]: value };
57	      try {
58	        localStorage.setItem(KEY, JSON.stringify(next));
59	      } catch {
60	        // ignore quota / privacy-mode errors
61	      }
62	      return next;
63	    });
64	  }, []);
65	
66	  return [tweaks, setTweak];
67	}
