60	}
61	type SpeechRecognitionCtor = new () => SpeechRecognitionLike;
62	
63	function getRecognitionCtor(): SpeechRecognitionCtor | null {
64	  if (typeof window === "undefined") return null;
65	  const w = window as unknown as {
66	    SpeechRecognition?: SpeechRecognitionCtor;
67	    webkitSpeechRecognition?: SpeechRecognitionCtor;
68	  };
69	  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
70	}
