72	// Segment a streamed token buffer into speakable clauses (sentence end, or a
73	// clause break once long enough) so TTS starts on the first clause.
74	const SENTENCE_END = /[.!?](?=\s|$)/;
75	const CLAUSE_BREAK = /[,;:](?=\s)/;
76	const MIN_CLAUSE = 30;
77	
78	function nextClause(buf: string): [string, string] | null {
79	  const end = buf.match(SENTENCE_END);
80	  if (end && end.index != null) {
81	    const cut = end.index + 1;
82	    return [buf.slice(0, cut).trim(), buf.slice(cut)];
83	  }
84	  if (buf.length >= MIN_CLAUSE) {
85	    const c = buf.match(CLAUSE_BREAK);
86	    if (c && c.index != null) {
87	      const cut = c.index + 1;
88	      return [buf.slice(0, cut).trim(), buf.slice(cut)];
89	    }
90	  }
91	  return null;
92	}
