3	// Silero VAD running in the browser via onnxruntime-web (WASM). This is a neural
4	// voice-activity detector — it answers "is this speech / did the turn end?", NOT
5	// "what was said?" (that's Mistral's job). It replaces the old energy/RMS gate,
6	// which sat below most rooms' noise floor and never fired end-of-turn.
7	//
8	// Model: loaded at call-start from jsDelivr, pinned to a silero-vad release tag
9	// (same CDN we already use for the ORT WASM runtime — no repo binary). Source of
10	// truth: github.com/snakers4/silero-vad → src/silero_vad/data/silero_vad.onnx
11	// (NOT files/silero_vad.onnx, which is the legacy h/c model). v6.x is a packaging
12	// change; the ONNX interface is unchanged. Interface: inputs
13	// input[1,576]/state[2,1,128]/sr → outputs output/stateN (see CONTEXT_SAMPLES).
14	//
15	// The model is stateful: each 512-sample (32 ms @ 16 kHz) frame is run in order,
16	// carrying the [2,1,128] state forward. A hysteresis state machine
17	// (positive/negative thresholds + a redemption grace period) turns the per-frame
18	// speech probability into onSpeechStart / onSpeechEnd events.
19	//
20	// Inference is async and must stay sequential (state ordering), so frames are
21	// queued and drained one at a time. onnxruntime-web is dynamically imported so it
22	// never touches the server bundle and only loads when a call actually starts.
23	
24	import type * as Ort from "onnxruntime-web";
25	
26	const SAMPLE_RATE = 16000;
27	const FRAME_SAMPLES = 512; // Silero @ 16 kHz = 32 ms
28	// The official Silero ONNX wrapper prepends the last 64 samples of the previous
29	// frame as context, so each inference sees 64 + 512 = 576 samples. The current
30	// snakers4 model (silero-vad v6.x release) requires this — without it the model
31	// returns ~0.1 on clear speech. (ricky0123/vad's older bundled export took 512
32	// directly; that's the difference between the two same-graph models.)
33	const CONTEXT_SAMPLES = 64;
34	const FRAME_MS = (FRAME_SAMPLES / SAMPLE_RATE) * 1000;
35	const ORT_VERSION = "1.27.0"; // keep in sync with package.json onnxruntime-web
36	// Pinned silero-vad release tag → reproducible model bytes via jsDelivr's GitHub CDN.
37	const SILERO_TAG = "v6.2.1";
38	const MODEL_URL = `https://cdn.jsdelivr.net/gh/snakers4/silero-vad@${SILERO_TAG}/src/silero_vad/data/silero_vad.onnx`;
39	
40	export interface SileroOptions {
41	  /** Override the model URL (defaults to the pinned jsDelivr CDN model). */
42	  modelUrl?: string;
43	  /** Frame prob above this ⇒ speech. */
44	  positiveSpeechThreshold?: number;
45	  /** Frame prob below this (while speaking) ⇒ counts toward end-of-turn. */
46	  negativeSpeechThreshold?: number;
47	  /** Silence after speech that ends the turn — the "let me finish" window. */
48	  redemptionMs?: number;
49	  /** Shortest run of speech that counts as a real turn (else a misfire). */
50	  minSpeechMs?: number;
51	  onSpeechStart?: () => void;
52	  onSpeechEnd?: () => void;
53	  onMisfire?: () => void;
54	  onError?: (message: string) => void;
55	}
56	
57	let ortPromise: Promise<typeof import("onnxruntime-web")> | null = null;
58	function loadOrt(): Promise<typeof import("onnxruntime-web")> {
59	  return (ortPromise ??= import("onnxruntime-web"));
60	}
61	
62	export class SileroVad {
63	  private readonly ort: typeof import("onnxruntime-web");
64	  private readonly session: Ort.InferenceSession;
65	  private readonly sr: Ort.Tensor;
66	  private state: Ort.Tensor;
67	
68	  // Thresholds + grace, in frames.
69	  private readonly pos: number;
70	  private readonly neg: number;
71	  private readonly redemptionFrames: number;
72	  private readonly minSpeechFrames: number;
73	  private readonly cb: SileroOptions;
74	
75	  // Sequential-inference queue + leftover (<512) samples.
76	  private leftover = new Float32Array(0);
77	  private queue: Float32Array[] = [];
78	  private draining = false;
79	  // Rolling 64-sample context prepended to each frame (official Silero usage).
80	  private context = new Float32Array(CONTEXT_SAMPLES);
81	
82	  // Hysteresis state machine.
83	  private speaking = false;
84	  private redemption = 0;
85	  private speechFrames = 0;
86	  private paused = true;
87	  private closed = false;
88	
89	  private constructor(
90	    ort: typeof import("onnxruntime-web"),
91	    session: Ort.InferenceSession,
92	    opts: SileroOptions,
93	  ) {
94	    this.ort = ort;
95	    this.session = session;
96	    this.cb = opts;
97	    this.pos = opts.positiveSpeechThreshold ?? 0.3;
98	    this.neg = opts.negativeSpeechThreshold ?? 0.25;
99	    this.redemptionFrames = Math.round((opts.redemptionMs ?? 900) / FRAME_MS);
100	    this.minSpeechFrames = Math.round((opts.minSpeechMs ?? 300) / FRAME_MS);
101	    this.sr = new ort.Tensor("int64", new BigInt64Array([BigInt(SAMPLE_RATE)]), [1]);
102	    this.state = SileroVad.freshState(ort);
103	  }
104	
105	  private static freshState(ort: typeof import("onnxruntime-web")): Ort.Tensor {
106	    return new ort.Tensor("float32", new Float32Array(2 * 1 * 128), [2, 1, 128]);
107	  }
108	
109	  static async create(opts: SileroOptions = {}): Promise<SileroVad> {
110	    const ort = await loadOrt();
111	    // Single-threaded WASM avoids needing COOP/COEP cross-origin isolation;
112	    // one 512-sample frame at a time is plenty fast.
113	    ort.env.wasm.numThreads = 1;
114	    ort.env.wasm.wasmPaths = `https://cdn.jsdelivr.net/npm/onnxruntime-web@${ORT_VERSION}/dist/`;
115	    const session = await ort.InferenceSession.create(opts.modelUrl ?? MODEL_URL, {
116	      executionProviders: ["wasm"],
117	    });
118	    return new SileroVad(ort, session, opts);
119	  }
120	
121	  /** Feed mic samples (16 kHz mono Float32). Buffers into 512-sample frames and
122	   *  runs them through the model in order. No-op while paused. */
123	  feed(samples: Float32Array): void {
124	    if (this.paused || this.closed) return;
125	    const merged = new Float32Array(this.leftover.length + samples.length);
126	    merged.set(this.leftover, 0);
127	    merged.set(samples, this.leftover.length);
128	    let offset = 0;
129	    for (; offset + FRAME_SAMPLES <= merged.length; offset += FRAME_SAMPLES) {
130	      this.queue.push(merged.slice(offset, offset + FRAME_SAMPLES));
131	    }
132	    this.leftover = merged.slice(offset);
133	    void this.drain();
134	  }
135	
136	  private async drain(): Promise<void> {
137	    if (this.draining) return;
138	    this.draining = true;
139	    try {
140	      while (this.queue.length > 0 && !this.closed) {
141	        const frame = this.queue.shift();
142	        if (!frame) break;
143	        const prob = await this.infer(frame);
144	        if (!this.paused) this.onProb(prob);
145	      }
146	    } catch (err) {
147	      this.cb.onError?.(err instanceof Error ? err.message : "VAD inference error");
148	    } finally {
149	      this.draining = false;
150	    }
151	  }
152	
153	  private async infer(frame: Float32Array): Promise<number> {
154	    // Prepend the rolling context → 64 + 512 = 576 samples, then carry the last
155	    // 64 samples of this frame forward (matches the official OnnxWrapper).
156	    const withCtx = new Float32Array(CONTEXT_SAMPLES + frame.length);
157	    withCtx.set(this.context, 0);
158	    withCtx.set(frame, CONTEXT_SAMPLES);
159	    this.context = frame.slice(frame.length - CONTEXT_SAMPLES);
160	    const input = new this.ort.Tensor("float32", withCtx, [1, withCtx.length]);
161	    const out = await this.session.run({ input, state: this.state, sr: this.sr });
162	    this.state = out.stateN as Ort.Tensor;
163	    return (out.output.data as Float32Array)[0];
164	  }
165	
166	  private onProb(p: number): void {
167	    if (p >= this.pos) {
168	      if (!this.speaking) {
169	        this.speaking = true;
170	        this.speechFrames = 0;
171	        this.redemption = 0;
172	        this.cb.onSpeechStart?.();
173	      }
174	      this.speechFrames++;
175	      this.redemption = 0;
176	    } else if (this.speaking) {
177	      if (p < this.neg) {
178	        this.redemption++;
179	        if (this.redemption >= this.redemptionFrames) {
180	          const real = this.speechFrames >= this.minSpeechFrames;
181	          this.speaking = false;
182	          this.redemption = 0;
183	          this.speechFrames = 0;
184	          if (real) this.cb.onSpeechEnd?.();
185	          else this.cb.onMisfire?.();
186	        }
187	      } else {
188	        // Between thresholds while speaking: sustain, cancel the redemption dip.
189	        this.redemption = 0;
190	        this.speechFrames++;
191	      }
192	    }
193	  }
194	
195	  /** Clear the turn/state machine (keeps the loaded session). */
196	  reset(): void {
197	    this.speaking = false;
198	    this.redemption = 0;
199	    this.speechFrames = 0;
200	    this.leftover = new Float32Array(0);
201	    this.queue = [];
202	    this.context = new Float32Array(CONTEXT_SAMPLES);
203	    this.state = SileroVad.freshState(this.ort);
204	  }
205	
206	  /** Begin detecting (entering the listening state). */
207	  resume(): void {
208	    this.reset();
209	    this.paused = false;
210	  }
211	
212	  /** Stop detecting (assistant speaking / muted) and drop any half-formed turn. */
213	  pause(): void {
214	    this.paused = true;
215	    this.reset();
216	  }
217	
218	  get isSpeaking(): boolean {
219	    return this.speaking;
220	  }
221	
222	  close(): void {
223	    this.closed = true;
224	    this.paused = true;
225	    this.queue = [];
226	    void this.session.release?.().catch(() => {});
227	  }
228	}
